.jfooter__top{display:flex;align-items:center;justify-content:space-between;gap:30px;padding-bottom:26px;border-bottom:1px solid var(--jfooter-ink)}.jfooter__top .jfooter__heading{max-width:900px}.jfooter__social{display:flex;align-items:center;gap:10px;flex:none;min-height:44px}.jfooter__arrow{display:grid;place-items:center;width:24px;height:24px;flex:none;border-radius:50%;background:#111;color:var(--jfooter-accent)}.jfooter__arrow svg{width:16px;height:16px}.jfooter__middle{display:grid;grid-template-columns:1fr 1fr 1.15fr 1.4fr;gap:32px;padding:30px 0;border-bottom:1px solid var(--jfooter-ink)}.jfooter__group summary{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:10px;pointer-events:none}.jfooter__group summary span{display:none}.jfooter__links{display:flex;flex-direction:column}.jfooter__links a{display:flex;align-items:center;min-height:36px;padding:4px 0;overflow-wrap:anywhere}.jfooter__aside{border-left:1px solid var(--jfooter-ink);padding-left:32px}.jfooter__aside>.jfooter__title{font-size:calc(var(--jfooter-title-size)*1.2);margin-bottom:16px}.jfooter__back{display:inline-flex;align-items:center;gap:10px;min-height:44px;text-decoration:underline!important;text-underline-offset:5px}.jfooter__newsletter{margin-top:10px}.jfooter__newsletter>summary{display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:44px;border-top:1px solid #1114}.jfooter__newsletter[open]>summary>span{transform:rotate(45deg)}.jfooter__form label{display:block;margin:12px 0 6px}.jfooter .jfooter__email{width:100%;min-height:46px;background:transparent;color:inherit;border:1px solid #1118;border-radius:3px;padding:10px;font-size:16px}.jfooter .jfooter__primary{display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:50px;width:100%;padding:8px 9px 8px 20px;border:1px solid #111;border-radius:999px;background:var(--jfooter-accent);color:#111;box-shadow:-2px 1px 0 #111;margin-top:12px;cursor:pointer}.jfooter__primary{transition:transform var(--jfooter-duration) ease}@media(hover:hover){.jfooter[data-motion=true] .jfooter__primary:hover{transform:translateY(-2px)}}@media(prefers-reduced-motion:reduce){.jfooter .jfooter__primary{transition:none!important;transform:none!important}}.jfooter[data-motion=false] .jfooter__primary{transition:none}.jfooter__primary .jfooter__arrow{width:32px;height:32px}.jfooter .jfooter__note{font-size:12px;margin-top:10px}.jfooter__mobile-actions{display:none}

