   <p class="jcorner__count jcorner__button-type">{{ number | plus: 1 | prepend: '0' }} / {{ section.settings.in_corner | escape }}</p>

   <div class="jcorner__item">{% if image != blank %}{% render 'june-photo-viewer', image: image, title: product.title, type_class: 'jcorner__body' %}{% endif %}<div><h3 class="jcorner__title">{{ block.settings.name | default: product.title | escape }}</h3><p class="jcorner__body jcorner__spec">{{ block.settings.specification | escape }}</p><p class="jcorner__price jcorner__body">{% if product.price_varies %}{{ section.settings.from | escape }} {% endif %}{{ product.price | money }}</p><a class="jcorner__link jcorner__button-type" href="{{ product.url }}">{{ section.settings.detail | escape }}{{ arrow }}</a></div></div>

   {% unless product.available %}<p class="jcorner__body">{{ section.settings.unavailable | escape }}</p>{% endunless %}

